import random
import struct
import time

# Simple ASN.1/BER helpers for SNMP v1/v2c messages

# BER type tags
TAG_INTEGER = 0x02
TAG_OCTET_STRING = 0x04
TAG_NULL = 0x05
TAG_OID = 0x06
TAG_SEQUENCE = 0x30

# SNMP PDU tags
PDU_GETREQUEST = 0xA0
PDU_GETNEXTREQUEST = 0xA1
PDU_GETRESPONSE = 0xA2
PDU_SETREQUEST = 0xA3
PDU_TRAP = 0xA4  # v1 trap
PDU_GETBULKREQUEST = 0xA5
PDU_INFORMREQUEST = 0xA6
PDU_TRAP2 = 0xA7  # v2c trap
PDU_REPORT = 0xA8

# Common enterprise OIDs as bases
OIDS = [
    [1,3,6,1,2,1],              # mib-2
    [1,3,6,1,2,1,1],            # system
    [1,3,6,1,2,1,2],            # interfaces
    [1,3,6,1,2,1,25],           # host-resources-mib
    [1,3,6,1,4,1,8072],         # net-snmp
]


def _ber_len(length: int) -> bytes:
    if length < 0x80:
        return bytes([length])
    b = []
    while length > 0:
        b.append(length & 0xFF)
        length >>= 8
    b.reverse()
    return bytes([0x80 | len(b)]) + bytes(b)


def _ber(tag: int, payload: bytes) -> bytes:
    return bytes([tag]) + _ber_len(len(payload)) + payload


def ber_integer(val: int) -> bytes:
    # Two's complement minimal encoding
    if val == 0:
        content = b"\x00"
    else:
        neg = val < 0
        v = -val if neg else val
        out = bytearray()
        while v:
            out.append(v & 0xFF)
            v >>= 8
        out.reverse()
        # add sign extension if needed
        if neg:
            # convert to two's complement width
            # grow until high bit set
            carry = 1
            for i in range(len(out)):
                out[i] ^= 0xFF
            # add one
            for i in range(len(out)-1, -1, -1):
                nv = out[i] + carry
                out[i] = nv & 0xFF
                carry = 1 if nv > 0xFF else 0
            if out[0] & 0x80 == 0:
                out = bytearray([0xFF]) + out
        else:
            if out[0] & 0x80:
                out = bytearray([0x00]) + out
        content = bytes(out)
    return _ber(TAG_INTEGER, content)


def ber_octet_string(s: bytes) -> bytes:
    return _ber(TAG_OCTET_STRING, s)


def ber_null() -> bytes:
    return _ber(TAG_NULL, b"")


def ber_oid(oid: list[int]) -> bytes:
    if len(oid) < 2:
        oid = [1,3] + oid
    first = 40*oid[0] + oid[1]
    body = bytearray([first])
    for subid in oid[2:]:
        # base-128 encoding
        stack = []
        if subid == 0:
            stack = [0]
        else:
            while subid > 0:
                stack.append(subid & 0x7F)
                subid >>= 7
            stack.reverse()
        for i, v in enumerate(stack):
            if i != len(stack)-1:
                body.append(0x80 | v)
            else:
                body.append(v)
    return _ber(TAG_OID, bytes(body))


def ber_sequence(tag: int, parts: list[bytes]) -> bytes:
    return _ber(tag, b"".join(parts))


def make_varbind(oid: list[int], value_kind: str, rnd: random.Random) -> bytes:
    # value_kind: 'null', 'int', 'str'
    if value_kind == 'null':
        val = ber_null()
    elif value_kind == 'int':
        val = ber_integer(rnd.randint(-10, 100000))
    else:
        # string
        # include some interesting byte patterns
        choices = [
            b"", b"\x00", b"public", b"uwsgi", b"test", bytes([0]*8),
        ]
        s = rnd.choice(choices)
        if rnd.random() < 0.5:
            s = s + rnd.randbytes(rnd.randint(0, 8))
        val = ber_octet_string(s)
    return ber_sequence(TAG_SEQUENCE, [ber_oid(oid), val])


def make_pdu(pdu_tag: int, request_id: int, error_status: int, error_index: int, varbinds: list[bytes]) -> bytes:
    vbl = ber_sequence(TAG_SEQUENCE, varbinds)
    return ber_sequence(pdu_tag, [
        ber_integer(request_id),
        ber_integer(error_status),
        ber_integer(error_index),
        vbl,
    ])


def make_message(version: int, community: bytes, pdu: bytes) -> bytes:
    return ber_sequence(TAG_SEQUENCE, [
        ber_integer(version),
        ber_octet_string(community),
        pdu,
    ])


def build_v1_trap(rnd: random.Random) -> bytes:
    # v1 Trap-PDU layout:
    # [enterprise OID][agent-addr (OCTET STRING 4 bytes)][generic-trap INTEGER]
    # [specific-trap INTEGER][time-stamp INTEGER][varbind list]
    enterprise = ber_oid(rnd.choice(OIDS) + [rnd.randint(1,50)])
    agent_addr = ber_octet_string(bytes([127,0,0,1]))
    generic = ber_integer(rnd.choice([0,1,2,3,4,5,6]))
    specific = ber_integer(rnd.randint(0, 10))
    timestamp = ber_integer(rnd.randint(0, 3600000))
    # varbinds
    vbs = []
    for _ in range(rnd.randint(1, 4)):
        base = rnd.choice(OIDS)
        oid = base + [rnd.randint(1,50), rnd.randint(1,50)]
        kind = rnd.choice(['null','int','str'])
        vbs.append(make_varbind(oid, kind, rnd))
    vbl = ber_sequence(TAG_SEQUENCE, vbs)
    pdu = ber_sequence(PDU_TRAP, [enterprise, agent_addr, generic, specific, timestamp, vbl])
    # version 0 for SNMPv1
    return make_message(0, b"public", pdu)


def build_v2c_pdu(rnd: random.Random) -> bytes:
    pdu_tag = rnd.choice([PDU_GETREQUEST, PDU_GETNEXTREQUEST, PDU_SETREQUEST, PDU_GETBULKREQUEST, PDU_TRAP2, PDU_INFORMREQUEST])
    req_id = rnd.randint(1, 2**31-1)
    if pdu_tag == PDU_GETBULKREQUEST:
        # For GETBULK, the second and third integers are non-repeaters and max-repetitions
        non_rep = rnd.randint(0, 5)
        max_rep = rnd.randint(1, 5)
        vbs = []
        for _ in range(rnd.randint(1, 4)):
            base = rnd.choice(OIDS)
            oid = base + [rnd.randint(1,100)]
            vbs.append(make_varbind(oid, 'null', rnd))
        vbl = ber_sequence(TAG_SEQUENCE, vbs)
        pdu = ber_sequence(PDU_GETBULKREQUEST, [
            ber_integer(req_id),
            ber_integer(non_rep),
            ber_integer(max_rep),
            vbl,
        ])
    else:
        vbs = []
        for _ in range(rnd.randint(1, 5)):
            base = rnd.choice(OIDS)
            oid = base + [rnd.randint(1,100), rnd.randint(0,10)]
            kind = 'null' if pdu_tag in (PDU_GETREQUEST, PDU_GETNEXTREQUEST) else rnd.choice(['int','str','null'])
            vbs.append(make_varbind(oid, kind, rnd))
        pdu = make_pdu(pdu_tag, req_id, 0, 0, vbs)
    return pdu


def generate(seed: int) -> bytes:
    rnd = random.Random(seed)
    # Choose between crafting different valid SNMP datagrams to exercise manage_snmp
    mode = rnd.choice(['v1_trap', 'v2c_req', 'mix'])

    bufs = []
    if mode == 'v1_trap':
        bufs.append(build_v1_trap(rnd))
    elif mode == 'v2c_req':
        # Build 1-3 v2c PDUs with varying communities
        for _ in range(rnd.randint(1, 2)):
            community = rnd.choice([b"public", b"private", b"uwsgi", b"monitor", b"public\x00"])
            msg = make_message(1, community, build_v2c_pdu(rnd))
            bufs.append(msg)
    else:
        # Mix v1 trap and one v2c request in a single datagram stream is unusual over UDP,
        # but the fuzzer will pass a single payload buffer; pick the more interesting one.
        # We choose one and possibly prepend a small padding community message to vary parsing.
        bufs.append(rnd.choice([build_v1_trap(rnd), make_message(1, b"public", build_v2c_pdu(rnd))]))

    payload = b"".join(bufs)
    # Ensure we stay within the fuzzer's 512-byte cap and overall guidance (<4096)
    if len(payload) > 480:
        payload = payload[:480]
    return payload
